with kept_keys as (select city, id from customers except all select city, id from customers where credit_limit between 9300 and 13100), kept_rows as (select s.* from customers s join kept_keys k on s.city = k.city and s.id = k.id) select name, email, city, segment, signup_date, case when segment rlike '^(Consumer|Corporate)$' then 'GROUP_B' else 'EXTENDED' end as segment_zone from kept_rows order by segment_zone desc;
